import numpy as np

def deflection_from_moment(x, M, EI, xa, xb):
    """Deflection v(x) with v(xa) = v(xb) = 0, from moment samples M(x)."""
    x = np.asarray(x, dtype=float)
    return np.zeros_like(x)

